package scan

import (
	"fmt"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/netproxy"
)

// RunsInContainer reports whether one of ids would run from an image: from the
// detection when it holds the tool, else from the configured source, where only
// "image" is a container for certain (auto may find a binary). A tool that
// cannot run runs nowhere, so it never counts.
func RunsInContainer(r *Report, tools config.ScanTools, ids []ToolID) bool {
	for _, id := range ids {
		if st, ok := r.status(id); ok {
			if st.Available && st.Source == ToolSourceContainer {
				return true
			}
			continue
		}
		if cfg := tools.Tool(string(id)); cfg != nil && cfg.Source == config.ToolSourceImage {
			return true
		}
	}
	return false
}

// status is the detection of one tool, and whether the report holds it. It is
// safe on a nil report.
func (r *Report) status(id ToolID) (ToolStatus, bool) {
	if r == nil {
		return ToolStatus{}, false
	}
	st, ok := r.Tools[id]
	return st, ok
}

// ContainerProxyWarning is the footer text when fwd names a loopback proxy and a
// containerised tool is about to run; "" otherwise. A scanner container has its
// own loopback, so a proxy on this machine's cannot be reached from it. The text
// carries the variable as it was read and the display form of its value, never
// the raw value, so no credential reaches the footer.
func ContainerProxyWarning(fwd netproxy.Forward, containerised bool) string {
	if !containerised {
		return ""
	}
	variable, display, ok := fwd.Loopback()
	if !ok {
		return ""
	}
	return fmt.Sprintf("%s is %s, on this machine's loopback: scanner containers cannot reach it", variable, display)
}
diff --git i/internal/app/jobs.go w/internal/app/jobs.go
index 32df4d46..be0a8ec7 100644
--- i/internal/app/jobs.go
+++ w/internal/app/jobs.go
@@ -5,8 +5,16 @@ import (

 	"github.com/anthnel/devdesk/internal/command"
 	"github.com/anthnel/devdesk/internal/jobs"
+	"github.com/anthnel/devdesk/internal/netproxy"
+	"github.com/anthnel/devdesk/internal/scan"
+	"github.com/anthnel/devdesk/internal/ui/components"
 )

+// containerForward is the proxy environment of this process. A variable so a
+// test can set it (TestMain empties it, so a developer's own HTTPS_PROXY never
+// reaches one).
+var containerForward = netproxy.ContainerForward
+
 // changedMsg is the snapshot the router broadcasts.
 func (a *App) changedMsg() jobs.ChangedMsg {
 	return jobs.ChangedMsg{
@@ -46,9 +54,36 @@ func (a *App) handleStartJobs(msg jobs.StartMsg) (tea.Model, tea.Cmd) {
 	if msg.Work != nil {
 		cmds = append(cmds, msg.Work(run.Context))
 	}
+	if warn := a.containerProxyWarning(run.Kind); warn != nil {
+		cmds = append(cmds, warn)
+	}
 	return a, tea.Batch(cmds...)
 }

+// containerProxyWarning is the footer Warning for a run about to start a scanner
+// container while the proxy variables name this machine's loopback, which the
+// container cannot reach (DEVDESK-583). Nil when there is nothing to say. It is
+// computed in Update from the detection already held, with no I/O (Rule 110),
+// and spoken through the footer (Rule 128). Every launch warns again.
+func (a *App) containerProxyWarning(kind jobs.Kind) tea.Cmd {
+	var ids []scan.ToolID
+	switch {
+	case kind == jobs.KindScan:
+		ids = scan.Required(a.config.Scan.Categories)
+	case kind == jobs.KindPull && a.config.Scan.VerifiesImages():
+		// A verified pull runs cosign (hypothesis H3 of the plan).
+		ids = []scan.ToolID{scan.ToolCosign}
+	default:
+		return nil
+	}
+	containerised := scan.RunsInContainer(a.sharedState.Tools, a.config.Scan.Tools, ids)
+	text := scan.ContainerProxyWarning(containerForward(), containerised)
+	if text == "" {
+		return nil
+	}
+	return components.PostFooter(components.LevelWarning, text)
+}
+
 // routeWork applies a progress message to the registry and hands it to the view
 // that owns it.
 //
diff --git i/internal/scan/run.go w/internal/scan/run.go
index 06703127..e5637b3a 100644
--- i/internal/scan/run.go
+++ w/internal/scan/run.go
@@ -110,7 +110,10 @@ func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) (

 	// Stderr is consumed two ways: streamed to progressFn while the tool runs,
 	// and kept so a failure can be reported with the tool's own diagnostic.
+	// What is kept stays raw: waitErr redacts it, on both paths. What is
+	// streamed is redacted line by line, since it leaves before the tool exits.
 	var stderr bytes.Buffer
+	redact := proxyForward().Redactor()
 	if progressFn != nil {
 		pipe, err := cmd.StderrPipe()
 		if err == nil {
@@ -125,7 +128,7 @@ func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) (
 					}
 					stderr.WriteString(line)
 					stderr.WriteByte('\n')
-					progressFn(line)
+					progressFn(redact(line))
 				}
 				// A read failure on the progress pipe is not a scan failure:
 				// the report comes back on stdout, and the tool's exit code
@@ -162,7 +165,9 @@ func finish(name string, cmd *exec.Cmd, stdout, stderr *bytes.Buffer) ([]byte, e
 }

 // waitErr turns a non-zero exit into an *exitError carrying the code, and
-// leaves anything else (a killed process, a broken pipe) as it is.
+// leaves anything else (a killed process, a broken pipe) as it is. The tool's
+// diagnostic, from the buffer or from os/exec's ExitError.Stderr, is stripped of
+// the proxy credentials first (DEVDESK-583).
 func waitErr(name string, err error, stderr string) error {
 	if err == nil {
 		return nil
@@ -172,7 +177,7 @@ func waitErr(name string, err error, stderr string) error {
 		if stderr == "" {
 			stderr = string(exitErr.Stderr)
 		}
-		return &exitError{Code: exitErr.ExitCode(), Stderr: stderr}
+		return &exitError{Code: exitErr.ExitCode(), Stderr: proxyForward().Redact(stderr)}
 	}
 	return fmt.Errorf("%s failed: %w", name, err)
 }
