		{"NO_PROXY alone", map[string]string{"NO_PROXY": "127.0.0.1,localhost"}, jobs.KindScan, []scan.ToolID{scan.ToolTrivy}, nil},
		{"loopback proxy, a sync", loopbackProxy, jobs.KindSync, []scan.ToolID{scan.ToolTrivy}, nil},
